import jakarta.persistence.*; import java.math.*; import java.time.*; import br.com.fiap.bank.plataforma.domain.StatusSolicitacao; @Entity @Table(name="tb_solicitacao_credito") public class SolicitacaoCreditoJpaEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(name="cpf_cliente",nullable=false,length=11) public String cpfCliente; @Column(name="nome_cliente",nullable=false) public String nomeCliente; @Column(name="tipo_credito",nullable=false) public String tipoCredito; @Column(name="valor_solicitado",nullable=false,precision=15,scale=2) public BigDecimal valorSolicitado; @Column(name="quantidade_parcelas",nullable=false) public Integer quantidadeParcelas; @Column(name="renda_mensal",nullable=false,precision=15,scale=2) public BigDecimal rendaMensal; public Integer scoreCredito; @Enumerated(EnumType.STRING) @Column(nullable=false) public StatusSolicitacao status; @Column(name="parecer_operador",length=500) public String parecerOperador; public Boolean scrRestricoes; public Integer scoreBureau; public LocalDateTime dataSolicitacao; public LocalDateTime dataAtualizacao; }
